:root {
  font-family: system-ui, sans-serif;
  color: #192d35;
  background: #f3f6f5;
  line-height: 1.5;
}
* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 820px; margin: 64px auto; padding: 0 24px; }
h1 { font-size: 2.5rem; line-height: 1.2; margin: 8px 0 32px; overflow-wrap: anywhere; }
h2 { font-size: 1.25rem; margin: 36px 0 16px; }
.eyebrow { font-size: .75rem; font-weight: 700; letter-spacing: .12em; color: #526d72; margin-top: 28px; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.create-controls { display: flex; gap: 12px; }
input, button { font: inherit; border-radius: 8px; padding: 11px 16px; }
input { min-width: 0; flex: 1; border: 1px solid #83999d; background: white; }
button { cursor: pointer; border: 1px solid #17665c; background: #17665c; color: white; font-weight: 600; }
button:hover { background: #104c44; }
button:disabled { cursor: default; opacity: .55; }
.secondary { color: #17665c; background: white; }
.secondary:hover { background: #e9f3f0; }
:focus-visible { outline: 3px solid #bf7014; outline-offset: 3px; }
.project-list { border: 1px solid #cad7d6; background: white; border-radius: 12px; overflow: hidden; }
.project-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 20px; padding: 20px; }
.project-row + .project-row { border-top: 1px solid #dde5e3; }
.project-name { font-weight: 600; overflow-wrap: anywhere; min-width: 0; }
